{"function": "() => {
    // First, get the complete list again to ensure we have all presidents
    const tables = document.querySelectorAll('table');
    let targetTable = null;

    for (const table of tables) {
        const headers = table.querySelectorAll('th');
        let hasBirthplace = false;
        let hasState = false;

        for (const header of headers) {
            const text = header.textContent || '';
            if (text.includes('Birthplace')) hasBirthplace = true;
            if (text.includes('State')) hasState = true;
        }

        if (hasBirthplace && hasState) {
            targetTable = table;
            break;
        }
    }

    if (!targetTable) return { error: 'Table not found' };

    const rows = targetTable.querySelectorAll('tr');
    const result = [];
    const uniqueCities = new Map(); // key: "city, state"

    for (const row of rows) {
        const cells = row.querySelectorAll('td');
        if (cells.length >= 4) {
            const dateCell = cells[0].textContent.trim();
            const nameCell = cells[1].textContent.trim();
            const birthplaceCell = cells[2].textContent.trim();
            const stateCell = cells[3].textContent.trim();

            let state = stateCell.replace('†', '').trim();

            // Clean up birthplace - remove "Region" from Waxhaws
            let birthplace = birthplaceCell;
            if (birthplace.includes('Region')) {
                birthplace = birthplace.replace('Region', '').trim();
            }

            result.push({
                president: nameCell,
                birthplace: birthplace,
                state: state,
                dateOfBirth: dateCell
            });

            // Create unique key
            const cityKey = `${birthplace}, ${state}`;
            if (!uniqueCities.has(cityKey)) {
                uniqueCities.set(cityKey, {
                    city: birthplace,
                    state: state,
                    presidents: [nameCell]
                });
            } else {
                uniqueCities.get(cityKey).presidents.push(nameCell);
            }
        }
    }

    // Convert Map to array
    const uniqueCitiesArray = Array.from(uniqueCities.values()).map(city => ({
        city: city.city,
        state: city.state,
        presidents: city.presidents
    }));

    return {
        allPresidents: result,
        uniqueCities: uniqueCitiesArray
    };
}"}

