{"function": "() => {
    // Find the main table with birthplaces
    const tables = document.querySelectorAll('table');
    let targetTable = null;

    // Look for the table with the specific header structure
    for (const table of tables) {
        const headers = table.querySelectorAll('th');
        let hasBirthplace = false;
        let hasState = false;

        for (const header of headers) {
            const text = header.textContent || '';
            if (text.includes('Birthplace')) hasBirthplace = true;
            if (text.includes('State')) hasState = true;
        }

        if (hasBirthplace && hasState) {
            targetTable = table;
            break;
        }
    }

    if (!targetTable) {
        return { error: 'Table not found' };
    }

    // Extract rows
    const rows = targetTable.querySelectorAll('tr');
    const result = [];

    for (const row of rows) {
        const cells = row.querySelectorAll('td');
        if (cells.length >= 4) {
            // Extract data from cells
            const dateCell = cells[0].textContent.trim();
            const nameCell = cells[1].textContent.trim();
            const birthplaceCell = cells[2].textContent.trim();
            const stateCell = cells[3].textContent.trim();

            // Clean up state cell (remove † symbol)
            let state = stateCell.replace('†', '').trim();

            result.push({
                president: nameCell,
                birthplace: birthplaceCell,
                state: state,
                dateOfBirth: dateCell
            });
        }
    }

    return result;
}"}

