{"function": "async () => {
    // Function to geocode a city using Nominatim
    async function geocodeCity(city, state) {
        const query = encodeURIComponent(`${city}, ${state}, United States`);
        const url = `https://nominatim.openstreetmap.org/search?q=${query}&format=json&limit=1`;

        try {
            const response = await fetch(url, {
                headers: {
                    'User-Agent': 'USPresidentsGeocoding/1.0'
                }
            });

            if (!response.ok) {
                throw new Error(`HTTP error: ${response.status}`);
            }

            const data = await response.json();

            if (data && data.length > 0) {
                return {
                    lat: parseFloat(data[0].lat),
                    lon: parseFloat(data[0].lon),
                    display_name: data[0].display_name,
                    found: true
                };
            } else {
                return {
                    lat: null,
                    lon: null,
                    display_name: null,
                    found: false
                };
            }
        } catch (error) {
            console.error(`Error geocoding ${city}, ${state}:`, error);
            return {
                lat: null,
                lon: null,
                display_name: null,
                found: false,
                error: error.message
            };
        }
    }

    // Get the list of unique cities from earlier
    const tables = document.querySelectorAll('table');
    let targetTable = null;

    for (const table of tables) {
        const headers = table.querySelectorAll('th');
        let hasBirthplace = false;
        let hasState = false;

        for (const header of headers) {
            const text = header.textContent || '';
            if (text.includes('Birthplace')) hasBirthplace = true;
            if (text.includes('State')) hasState = true;
        }

        if (hasBirthplace && hasState) {
            targetTable = table;
            break;
        }
    }

    if (!targetTable) return { error: 'Table not found' };

    const rows = targetTable.querySelectorAll('tr');
    const uniqueCities = new Map();

    for (const row of rows) {
        const cells = row.querySelectorAll('td');
        if (cells.length >= 4) {
            const nameCell = cells[1].textContent.trim();
            const birthplaceCell = cells[2].textContent.trim();
            const stateCell = cells[3].textContent.trim();

            let state = stateCell.replace('†', '').trim();
            let birthplace = birthplaceCell;
            if (birthplace.includes('Region')) {
                birthplace = birthplace.replace('Region', '').trim();
            }

            const cityKey = `${birthplace}, ${state}`;
            if (!uniqueCities.has(cityKey)) {
                uniqueCities.set(cityKey, {
                    city: birthplace,
                    state: state,
                    presidents: [nameCell]
                });
            } else {
                uniqueCities.get(cityKey).presidents.push(nameCell);
            }
        }
    }

    // Convert to array
    const citiesArray = Array.from(uniqueCities.values());

    // Return the cities array for now (we'll geocode later)
    return {
        cities: citiesArray,
        totalCities: citiesArray.length
    };
}"}

