{"function": "() => {
    // Get all data again and extract unique city-state pairs
    const tables = document.querySelectorAll('table');
    let targetTable = null;

    for (let table of tables) {
        const headers = table.querySelectorAll('th');
        let hasBirthplaceHeader = false;
        let hasStateHeader = false;

        for (let header of headers) {
            const text = header.textContent.trim();
            if (text.includes('Birthplace')) hasBirthplaceHeader = true;
            if (text.includes('State') && text.includes('birth')) hasStateHeader = true;
        }

        if (hasBirthplaceHeader && hasStateHeader) {
            targetTable = table;
            break;
        }
    }

    if (!targetTable) return null;

    const rows = targetTable.querySelectorAll('tr');
    const cityStateSet = new Set();
    const pairs = [];

    for (let row of rows) {
        const cells = row.querySelectorAll('td');
        if (cells.length >= 4) {
            const birthplaceCell = cells[2];
            const birthplaceLink = birthplaceCell.querySelector('a');
            let city = birthplaceLink ? birthplaceLink.textContent.trim() : birthplaceCell.textContent.trim();

            const stateCell = cells[3];
            const stateLink = stateCell.querySelector('a');
            let state = stateLink ? stateLink.textContent.trim() : stateCell.textContent.trim();

            state = state.replace('†', '').trim();

            // Clean up city names (remove "Region" etc.)
            city = city.replace(' Region', '').trim();

            if (city && state) {
                const key = `${city}, ${state}`;
                if (!cityStateSet.has(key)) {
                    cityStateSet.add(key);
                    pairs.push({city, state});
                }
            }
        }
    }

    return Array.from(pairs);
}"}

