    const match = coordText.match(/(\d+)°(\d+)′(\d+)″([NS])\s+(\d+)°(\d+)′(\d+)″([EW])/);
    if (!match) return null;

    const [_, latDeg, latMin, latSec, latDir, lonDeg, lonMin, lonSec, lonDir] = match;

    // Convert DMS to decimal degrees
    const lat = parseInt(latDeg) + parseInt(latMin)/60 + parseInt(latSec)/3600;
    const lon = parseInt(lonDeg) + parseInt(lonMin)/60 + parseInt(lonSec)/3600;

    const latDecimal = latDir === 'S' ? -lat : lat;
    const lonDecimal = lonDir === 'W' ? -lon : lon;

    return {
        lat: latDecimal,
        lon: lonDecimal,
        dms: coordText
    };
}"}

